// ─── Compliance ribbon — pharma only, embedded ───
function ComplianceRibbon({ profile, onTap, totals }) {
  if (!profile.complianceTracking) return null;
  const physician = profile.physicians[0];
  const projected = physician.ytd + totals.subtotal / profile.headcount;
  const willCross = projected > physician.threshold;
  const willApproach = projected > physician.threshold * 0.9 && !willCross;
  const color = willCross ? T.danger : willApproach ? T.warning : T.success;
  const bg = willCross ? T.dangerBg : willApproach ? T.warningBg : T.successBg;
  const pct = Math.min((projected / physician.threshold) * 100, 100);

  return (
    <button
      onClick={onTap}
      style={{
        height: 36,
        padding: "0 14px",
        flexShrink: 0,
        background: bg,
        border: "none",
        borderBottom: `1px solid ${color}22`,
        display: "flex",
        alignItems: "center",
        gap: 10,
        cursor: "pointer",
        textAlign: "left",
        width: "100%",
        fontFamily: font,
      }}
    >
      <span style={{ fontSize: 14 }}>⚖️</span>
      <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ fontSize: 11, fontWeight: 700, color }}>
          {physician.name}
        </span>
        <span
          style={{ fontSize: 11, color: T.textSecondary, fontFamily: fontMono }}
        >
          ${physician.ytd} → ${projected.toFixed(0)}
        </span>
        <div
          style={{
            flex: 1,
            height: 4,
            background: `${color}22`,
            borderRadius: 2,
            overflow: "hidden",
            maxWidth: 70,
          }}
        >
          <div
            style={{ width: `${pct}%`, height: "100%", background: color }}
          />
        </div>
      </div>
      <span
        style={{ fontSize: 11, fontWeight: 600, color, whiteSpace: "nowrap" }}
      >
        {willCross ? "⚠️ Over" : willApproach ? "Tight" : "✓ Safe"}
      </span>
    </button>
  );
}

