// ─── Status strip (3 mini stats) ───
function StatusStrip({ profile, totals, onTap }) {
  const dietaryCovered = profile.dietaryRestrictions.filter(
    (r) => r.count > 0,
  ).length;
  const dietaryTotal = profile.dietaryRestrictions.length;
  const overBudget = totals.subtotal > profile.budgetTotal;

  return (
    <button
      onClick={onTap}
      style={{
        width: "100%",
        display: "grid",
        gridTemplateColumns: "1fr 1fr 1fr",
        padding: "10px 14px",
        background: T.card,
        border: "none",
        borderBottom: `1px solid ${T.borderLight}`,
        cursor: "pointer",
        fontFamily: font,
        gap: 10,
        textAlign: "left",
      }}
    >
      <StatusStat
        icon="🪙"
        label="Bites"
        value={totals.totalBites.toLocaleString()}
        color={T.brand}
      />
      <StatusStat
        icon="🥗"
        label="Diet"
        value={`${dietaryCovered}/${dietaryTotal}`}
        color={T.success}
      />
      <StatusStat
        icon="💵"
        label="Budget"
        value={`$${totals.subtotal.toFixed(0)}`}
        color={overBudget ? T.danger : T.text}
        sub={`/${profile.budgetTotal}`}
      />
    </button>
  );
}

function StatusStat({ icon, label, value, color, sub }) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-start",
        minWidth: 0,
      }}
    >
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          marginBottom: 2,
        }}
      >
        <span style={{ fontSize: 11 }}>{icon}</span>
        <span
          style={{
            fontSize: 9,
            fontWeight: 700,
            color: T.textTertiary,
            letterSpacing: "0.06em",
            textTransform: "uppercase",
          }}
        >
          {label}
        </span>
      </div>
      <div style={{ display: "flex", alignItems: "baseline", gap: 1 }}>
        <span
          style={{
            fontSize: 14,
            fontWeight: 700,
            color,
            fontFamily: fontMono,
            lineHeight: 1,
          }}
        >
          {value}
        </span>
        {sub && (
          <span
            style={{ fontSize: 9, color: T.textTertiary, fontFamily: fontMono }}
          >
            {sub}
          </span>
        )}
      </div>
    </div>
  );
}

