// ─── Cart line item (single column, 60×60 thumb) ───
function CartLineItem({
  line,
  restaurant,
  restaurantKey,
  onChange,
  onRemove,
  onTapModifier,
  onTapPerPerson,
}) {
  const item = getItem(restaurantKey, line.itemId);
  if (!item) return null;
  const lineTotal = line.qty * line.basePrice;
  const hasOverrides = (line.perPersonOverrides || []).length > 0;

  return (
    <div
      style={{
        background: T.card,
        borderRadius: 12,
        border: `1px solid ${T.border}`,
        padding: 12,
        marginBottom: 8,
      }}
    >
      <div style={{ display: "flex", gap: 10, marginBottom: 10 }}>
        {/* Thumbnail */}
        <div
          style={{
            width: 60,
            height: 60,
            borderRadius: 9,
            flexShrink: 0,
            padding: 3,
            boxSizing: "border-box",
            background: `linear-gradient(135deg, ${restaurant.brandColor}, ${restaurant.brandColorAccent})`,
            overflow: "hidden",
            position: "relative",
          }}
        >
          {item.imageUrl ? (
            <img
              src={item.imageUrl}
              alt={item.name}
              style={{
                width: "100%",
                height: "100%",
                borderRadius: 6,
                objectFit: "cover",
                display: "block",
              }}
            />
          ) : (
            <div
              style={{
                width: "100%",
                height: "100%",
                borderRadius: 6,
                background: "rgba(255,255,255,0.1)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontSize: 22,
                filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.2))",
              }}
            >
              {restaurant.icon}
            </div>
          )}
        </div>

        {/* Item details */}
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              display: "flex",
              alignItems: "baseline",
              gap: 6,
              marginBottom: 2,
              flexWrap: "wrap",
            }}
          >
            <span
              style={{
                fontSize: 13,
                fontWeight: 600,
                color: T.text,
                fontFamily: fontDisplay,
                lineHeight: 1.2,
              }}
            >
              {item.name}
            </span>
            <span
              style={{
                fontSize: 10,
                color: T.textTertiary,
                fontFamily: fontMono,
              }}
            >
              ${line.basePrice.toFixed(2)}/ea
            </span>
          </div>
          {item.dietaryFlags?.includes("contains-nuts") && (
            <span
              style={{
                display: "inline-block",
                fontSize: 8,
                padding: "1px 5px",
                borderRadius: 3,
                background: T.warningBg,
                color: T.warning,
                fontWeight: 700,
                letterSpacing: "0.04em",
                marginBottom: 4,
              }}
            >
              CONTAINS NUTS
            </span>
          )}
          <div
            style={{
              fontSize: 10,
              color: T.textTertiary,
              marginBottom: 5,
              lineHeight: 1.4,
            }}
          >
            <span style={{ fontSize: 11 }}>👥</span> {line.appliesTo}
          </div>
        </div>

        {/* Total + qty stepper stacked */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-end",
            gap: 5,
            flexShrink: 0,
          }}
        >
          <div
            style={{
              fontSize: 14,
              fontWeight: 700,
              color: T.text,
              fontFamily: fontMono,
              lineHeight: 1,
            }}
          >
            ${lineTotal.toFixed(2)}
          </div>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 4,
              padding: 2,
              background: T.surface,
              borderRadius: 7,
            }}
          >
            <button
              onClick={() =>
                line.qty > 1
                  ? onChange({ ...line, qty: line.qty - 1 })
                  : onRemove()
              }
              style={qtyBtn}
            >
              −
            </button>
            <span
              style={{
                fontSize: 12,
                fontWeight: 700,
                color: T.text,
                fontFamily: fontMono,
                minWidth: 18,
                textAlign: "center",
              }}
            >
              {line.qty}
            </span>
            <button
              onClick={() => onChange({ ...line, qty: line.qty + 1 })}
              style={qtyBtn}
            >
              ＋
            </button>
          </div>
        </div>
      </div>

      {/* Modifier chips (full row below) */}
      {item.modifierGroups && item.modifierGroups.length > 0 && (
        <div
          style={{ display: "flex", flexWrap: "wrap", gap: 4, marginBottom: 8 }}
        >
          {item.modifierGroups.map((g) => (
            <button
              key={g.id}
              onClick={() => onTapModifier(line, g)}
              style={{
                padding: "4px 9px",
                borderRadius: 6,
                fontFamily: font,
                border: `1px solid ${T.border}`,
                background: T.card,
                fontSize: 10,
                cursor: "pointer",
                display: "inline-flex",
                alignItems: "center",
                gap: 4,
              }}
            >
              <span
                style={{
                  fontSize: 8,
                  color: T.textTertiary,
                  fontWeight: 700,
                  letterSpacing: "0.04em",
                  textTransform: "uppercase",
                }}
              >
                {g.name}:
              </span>
              <span style={{ color: T.text, fontWeight: 600 }}>
                {line.modifiers[g.id] || "—"}
              </span>
              <svg width="7" height="7" viewBox="0 0 12 12" fill="none">
                <path
                  d="M3 4.5L6 7.5L9 4.5"
                  stroke={T.textTertiary}
                  strokeWidth="1.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </button>
          ))}
        </div>
      )}

      {/* Per-person customization link */}
      <button
        onClick={() => onTapPerPerson(line)}
        style={{
          width: "100%",
          padding: "5px 8px",
          borderRadius: 6,
          border: "none",
          background: hasOverrides ? T.purpleBg : T.surface,
          color: hasOverrides ? T.purple : T.brand,
          fontSize: 10,
          fontWeight: 600,
          cursor: "pointer",
          fontFamily: font,
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span>
          {hasOverrides
            ? `✦ ${line.perPersonOverrides.length} customization`
            : "Customize individual orders"}
        </span>
        <svg width="9" height="9" viewBox="0 0 12 12" fill="none">
          <path
            d="M5 3l3 3-3 3"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
    </div>
  );
}

const qtyBtn = {
  width: 22,
  height: 22,
  borderRadius: 6,
  border: "none",
  background: T.card,
  color: T.text,
  fontSize: 12,
  fontWeight: 700,
  cursor: "pointer",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  fontFamily: font,
};

// ─── Modifier sheet ───
function ModifierSheet({
  open,
  line,
  group,
  restaurantKey,
  onSelect,
  onClose,
}) {
  if (!open || !line || !group) return null;
  const item = getItem(restaurantKey, line.itemId);
  return (
    <SheetWrapper
      onClose={onClose}
      title={`${item.name} — ${group.name}`}
      height="55%"
    >
      <div style={{ padding: "0 14px 24px" }}>
        {group.options.map((opt) => {
          const isSelected = line.modifiers[group.id] === opt;
          return (
            <button
              key={opt}
              onClick={() => {
                onSelect(opt);
                onClose();
              }}
              style={{
                width: "100%",
                padding: "12px 14px",
                marginBottom: 6,
                borderRadius: 11,
                background: isSelected ? T.brandLight : T.card,
                border: `1px solid ${isSelected ? T.brand : T.border}`,
                cursor: "pointer",
                fontFamily: font,
                textAlign: "left",
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                fontSize: 14,
                fontWeight: isSelected ? 600 : 500,
                color: isSelected ? T.brandDark : T.text,
              }}
            >
              <span>{opt}</span>
              {isSelected && (
                <div
                  style={{
                    width: 22,
                    height: 22,
                    borderRadius: "50%",
                    background: T.brand,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    color: "#fff",
                    fontSize: 12,
                    fontWeight: 700,
                  }}
                >
                  ✓
                </div>
              )}
            </button>
          );
        })}
      </div>
    </SheetWrapper>
  );
}

// ─── Per-person customization full-screen route ───
function PerPersonRoute({
  open,
  line,
  restaurantKey,
  profile,
  onClose,
  onAcceptAI,
}) {
  if (!open || !line) return null;
  const item = getItem(restaurantKey, line.itemId);

  // Build seat list
  const seats = useMemo(() => {
    const list = [];
    if (line.itemId === "med-bowl") {
      const veg = profile.dietaryRestrictions.find(
        (r) => r.tag === "Vegetarian",
      );
      const vegan = profile.dietaryRestrictions.find((r) => r.tag === "Vegan");
      const treeNut = profile.dietaryRestrictions.find(
        (r) => r.tag === "Tree nut allergy",
      );
      const indivs = veg?.individuals || [];
      for (let i = 0; i < line.qty; i++) {
        const name = indivs[i] || `Guest ${i + 1}`;
        const tags = [];
        if (vegan?.individuals?.includes(name))
          tags.push({ label: "Vegan", color: T.warning, bg: T.warningBg });
        if (treeNut?.individuals?.includes(name))
          tags.push({
            label: "Tree nut allergy",
            color: T.danger,
            bg: T.dangerBg,
          });
        list.push({ index: i, name, tags });
      }
    } else if (line.itemId === "power-bowl") {
      const treeNut = profile.dietaryRestrictions.find(
        (r) => r.tag === "Tree nut allergy",
      );
      const names = treeNut?.individuals || [];
      for (let i = 0; i < line.qty; i++) {
        const name = i < names.length ? names[i] : `Guest ${i + 1}`;
        const tags = [];
        if (treeNut?.individuals?.includes(name))
          tags.push({
            label: "Tree nut allergy",
            color: T.danger,
            bg: T.dangerBg,
          });
        list.push({ index: i, name, tags });
      }
    } else {
      for (let i = 0; i < line.qty; i++)
        list.push({ index: i, name: `Guest ${i + 1}`, tags: [] });
    }
    return list;
  }, [line, profile]);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: T.surface,
        zIndex: 50,
        display: "flex",
        flexDirection: "column",
        animation: "slideInRight 0.3s cubic-bezier(0.32, 0.72, 0, 1)",
      }}
    >
      {/* Top bar */}
      <div
        style={{
          height: 56,
          padding: "0 12px",
          flexShrink: 0,
          background: T.card,
          borderBottom: `1px solid ${T.border}`,
          display: "flex",
          alignItems: "center",
          gap: 10,
        }}
      >
        <button
          onClick={onClose}
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            border: "none",
            background: T.surface,
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path
              d="M10 4l-4 4 4 4"
              stroke={T.text}
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontSize: 13,
              fontWeight: 600,
              color: T.text,
              fontFamily: fontDisplay,
              lineHeight: 1.2,
            }}
          >
            Customize individual orders
          </div>
          <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 1 }}>
            {line.qty} × {item.name}
          </div>
        </div>
      </div>

      {/* Group default summary */}
      <div
        style={{
          padding: 14,
          background: T.card,
          borderBottom: `1px solid ${T.border}`,
          flexShrink: 0,
        }}
      >
        <div
          style={{
            fontSize: 9,
            fontWeight: 700,
            color: T.textTertiary,
            letterSpacing: "0.06em",
            textTransform: "uppercase",
            marginBottom: 6,
          }}
        >
          Group default
        </div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 5 }}>
          {Object.entries(line.modifiers).map(([key, val]) => (
            <span
              key={key}
              style={{
                fontSize: 11,
                padding: "3px 8px",
                borderRadius: 5,
                background: T.surface,
                border: `1px solid ${T.border}`,
                color: T.textSecondary,
              }}
            >
              <strong style={{ color: T.text }}>{key}:</strong>{" "}
              {Array.isArray(val) ? val.join(", ") : val}
            </span>
          ))}
        </div>
      </div>

      {/* Per-person cards */}
      <div style={{ flex: 1, overflowY: "auto", padding: "12px 14px 80px" }}>
        {seats.map((seat) => {
          const override = (line.perPersonOverrides || []).find(
            (o) => o.individual === seat.name,
          );
          return (
            <div
              key={seat.index}
              style={{
                padding: "10px 12px",
                marginBottom: 8,
                borderRadius: 11,
                background: T.card,
                border: `1px solid ${T.border}`,
                borderLeft:
                  seat.tags.length > 0
                    ? `3px solid ${seat.tags[0].color}`
                    : `1px solid ${T.border}`,
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  marginBottom: 6,
                }}
              >
                <span
                  style={{
                    fontSize: 12,
                    color: T.textTertiary,
                    fontFamily: fontMono,
                    width: 22,
                  }}
                >
                  {seat.index + 1}
                </span>
                <span
                  style={{
                    fontSize: 13,
                    fontWeight: 600,
                    color: T.text,
                    flex: 1,
                  }}
                >
                  {seat.name}
                </span>
                {seat.tags.map((t) => (
                  <span
                    key={t.label}
                    style={{
                      fontSize: 9,
                      padding: "2px 6px",
                      borderRadius: 4,
                      background: t.bg,
                      color: t.color,
                      fontWeight: 700,
                    }}
                  >
                    {t.label.includes("allergy") ? "⚠️" : "✦"} {t.label}
                  </span>
                ))}
              </div>
              {override ? (
                <div
                  style={{
                    fontSize: 11,
                    padding: "6px 10px",
                    borderRadius: 7,
                    background: T.purpleBg,
                    color: T.purple,
                    fontWeight: 600,
                    display: "flex",
                    alignItems: "center",
                    gap: 5,
                  }}
                >
                  <span>✦</span>
                  <span>Removed: {override.removed.join(", ")}</span>
                  <span
                    style={{
                      color: T.textTertiary,
                      fontWeight: 400,
                      marginLeft: "auto",
                    }}
                  >
                    · {override.reason}
                  </span>
                </div>
              ) : seat.tags.includes("Tree nut allergy") ? (
                <div
                  style={{
                    fontSize: 10,
                    color: T.warning,
                    fontStyle: "italic",
                  }}
                >
                  AI suggests: separate prep area
                </div>
              ) : (
                <div
                  style={{
                    fontSize: 10,
                    color: T.textTertiary,
                    fontStyle: "italic",
                  }}
                >
                  Group default
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* AI suggestion footer */}
      <div
        style={{
          padding: "10px 14px 14px",
          background: T.brandLight,
          borderTop: `1px solid ${T.border}`,
          flexShrink: 0,
        }}
      >
        <div
          style={{
            fontSize: 11,
            color: T.textSecondary,
            lineHeight: 1.4,
            marginBottom: 8,
          }}
        >
          <strong style={{ color: T.brand }}>AI suggests:</strong> Add "separate
          prep area, no tree nut contamination" for Sarah's bowl.
        </div>
        <button
          onClick={() => {
            onAcceptAI?.();
            onClose();
          }}
          style={{
            width: "100%",
            padding: "10px 14px",
            borderRadius: 10,
            border: "none",
            background: T.brand,
            color: "#fff",
            fontSize: 12,
            fontWeight: 700,
            cursor: "pointer",
            fontFamily: font,
          }}
        >
          Accept AI suggestions
        </button>
      </div>
    </div>
  );
}

// ─── Compare carts full-screen swiper ───
function CompareCartsRoute({ open, carts, profile, onClose, onPlaceOrder }) {
  const cartKeys = Object.keys(carts).filter(
    (k) => carts[k] && carts[k].length > 0 && MENUS[k]?.tier !== 3,
  );
  const [activeIdx, setActiveIdx] = useState(0);
  useEffect(() => {
    if (open) setActiveIdx(0);
  }, [open]);

  if (!open || cartKeys.length === 0) return null;
  const rkey = cartKeys[activeIdx];
  const restaurant = MENUS[rkey];
  const cart = carts[rkey];
  const totals = calcCartTotals(cart, restaurant);
  const overBudget = totals.subtotal > profile.budgetTotal;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: T.surface,
        zIndex: 50,
        display: "flex",
        flexDirection: "column",
        animation: "slideInRight 0.3s cubic-bezier(0.32, 0.72, 0, 1)",
      }}
    >
      {/* Top bar */}
      <div
        style={{
          height: 56,
          padding: "0 12px",
          flexShrink: 0,
          background: T.card,
          borderBottom: `1px solid ${T.border}`,
          display: "flex",
          alignItems: "center",
          gap: 10,
        }}
      >
        <button
          onClick={onClose}
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            border: "none",
            background: T.surface,
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <path
              d="M10 4l-4 4 4 4"
              stroke={T.text}
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontSize: 13,
              fontWeight: 600,
              color: T.text,
              fontFamily: fontDisplay,
            }}
          >
            Compare carts
          </div>
          <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 1 }}>
            {cartKeys.length} carts · pick one to place
          </div>
        </div>
        <span
          style={{ fontSize: 11, color: T.textTertiary, fontFamily: fontMono }}
        >
          {activeIdx + 1}/{cartKeys.length}
        </span>
      </div>

      {/* Tab pills */}
      <div
        style={{
          display: "flex",
          gap: 6,
          padding: "8px 14px",
          flexShrink: 0,
          background: T.card,
          borderBottom: `1px solid ${T.borderLight}`,
          overflowX: "auto",
        }}
      >
        {cartKeys.map((k, i) => {
          const r = MENUS[k];
          const isActive = i === activeIdx;
          return (
            <button
              key={k}
              onClick={() => setActiveIdx(i)}
              style={{
                padding: "6px 11px",
                borderRadius: 16,
                border: "none",
                flexShrink: 0,
                background: isActive
                  ? `linear-gradient(135deg, ${r.brandColor}, ${r.brandColorAccent})`
                  : T.surface,
                color: isActive ? "#fff" : T.text,
                fontSize: 11,
                fontWeight: 600,
                cursor: "pointer",
                fontFamily: font,
                display: "flex",
                alignItems: "center",
                gap: 4,
              }}
            >
              <span>{r.icon}</span>
              <span>{r.name}</span>
            </button>
          );
        })}
      </div>

      {/* Active cart hero + summary */}
      <div style={{ flex: 1, overflowY: "auto" }}>
        {/* Brand hero */}
        <div
          style={{
            position: "relative",
            height: 140,
            overflow: "hidden",
            background: restaurant.brandColor,
          }}
        >
          {restaurant.brandHeroUrl && (
            <img
              src={restaurant.brandHeroUrl}
              alt={restaurant.name}
              style={{
                position: "absolute",
                inset: 0,
                width: "100%",
                height: "100%",
                objectFit: "cover",
                objectPosition: "center 40%",
              }}
            />
          )}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: `linear-gradient(to bottom, ${restaurant.brandColor}40 0%, ${restaurant.brandColor}E0 100%)`,
            }}
          />
          <div
            style={{
              position: "absolute",
              bottom: 14,
              left: 16,
              right: 16,
              color: "#fff",
            }}
          >
            <div
              style={{
                fontSize: 22,
                fontWeight: 700,
                fontFamily: fontDisplay,
                textShadow: "0 1px 4px rgba(0,0,0,0.3)",
              }}
            >
              {restaurant.name}
            </div>
            <div style={{ fontSize: 11, opacity: 0.9, marginTop: 3 }}>
              {restaurant.cuisine} · ★ {restaurant.rating} ·{" "}
              {restaurant.baseRate}X Bites
            </div>
          </div>
        </div>

        {/* Comparison stats */}
        <div style={{ padding: 14 }}>
          <ComparisonRow
            label="Total"
            value={`$${totals.subtotal.toFixed(2)}`}
            accent={overBudget ? T.danger : T.text}
          />
          <ComparisonRow
            label="Per person"
            value={`$${(totals.subtotal / profile.headcount).toFixed(2)}`}
          />
          <ComparisonRow
            label="Bites earned"
            value={`${totals.totalBites.toLocaleString()} Bites`}
            accent={T.brand}
            highlight
          />
          <ComparisonRow
            label="Items"
            value={`${cart.reduce((s, l) => s + l.qty, 0)} portions`}
          />
          <ComparisonRow
            label="Dietary"
            value="Full coverage ✓"
            accent={T.success}
          />
          <ComparisonRow
            label="Same-day"
            value={restaurant.sameDay ? "Yes" : "No"}
          />

          {/* Place order CTA */}
          <button
            onClick={() => onPlaceOrder(rkey)}
            style={{
              width: "100%",
              padding: "13px 16px",
              marginTop: 16,
              borderRadius: 12,
              border: "none",
              background: `linear-gradient(135deg, ${T.brand}, ${T.brandDark})`,
              color: "#fff",
              fontSize: 14,
              fontWeight: 700,
              cursor: "pointer",
              fontFamily: font,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 8,
              boxShadow: `0 4px 16px ${T.brandGlow}`,
            }}
          >
            <span>🍴</span>
            <span>Place this order</span>
          </button>

          {/* Swipe hint */}
          {cartKeys.length > 1 && (
            <div
              style={{
                fontSize: 10,
                color: T.textTertiary,
                textAlign: "center",
                marginTop: 14,
                lineHeight: 1.5,
              }}
            >
              Tap pills above or use arrows to compare
            </div>
          )}
        </div>
      </div>

      {/* Bottom arrow nav */}
      {cartKeys.length > 1 && (
        <div
          style={{
            padding: "10px 14px",
            background: T.card,
            borderTop: `1px solid ${T.borderLight}`,
            flexShrink: 0,
            display: "flex",
            gap: 8,
            alignItems: "center",
          }}
        >
          <button
            onClick={() => setActiveIdx((i) => Math.max(i - 1, 0))}
            disabled={activeIdx === 0}
            style={{
              flex: 1,
              padding: "10px",
              borderRadius: 10,
              border: `1px solid ${T.border}`,
              background: T.surface,
              fontSize: 11,
              fontWeight: 600,
              cursor: activeIdx === 0 ? "default" : "pointer",
              opacity: activeIdx === 0 ? 0.4 : 1,
              fontFamily: font,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 5,
            }}
          >
            ← Previous
          </button>
          <button
            onClick={() =>
              setActiveIdx((i) => Math.min(i + 1, cartKeys.length - 1))
            }
            disabled={activeIdx === cartKeys.length - 1}
            style={{
              flex: 1,
              padding: "10px",
              borderRadius: 10,
              border: `1px solid ${T.border}`,
              background: T.surface,
              fontSize: 11,
              fontWeight: 600,
              cursor: activeIdx === cartKeys.length - 1 ? "default" : "pointer",
              opacity: activeIdx === cartKeys.length - 1 ? 0.4 : 1,
              fontFamily: font,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 5,
            }}
          >
            Next →
          </button>
        </div>
      )}
    </div>
  );
}

function ComparisonRow({ label, value, accent, highlight }) {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "9px 12px",
        marginBottom: 5,
        borderRadius: 8,
        background: highlight ? T.brandLight : T.surface,
        border: highlight ? `1px solid ${T.brand}33` : "none",
      }}
    >
      <span style={{ fontSize: 11, color: T.textSecondary, fontWeight: 500 }}>
        {label}
      </span>
      <span
        style={{
          fontSize: 13,
          color: accent || T.text,
          fontWeight: 700,
          fontFamily: fontMono,
        }}
      >
        {value}
      </span>
    </div>
  );
}

// ─── Cart drafts sheet ───
function CartDraftsSheet({
  open,
  carts,
  profile,
  activeRestaurant,
  onClose,
  onSwitch,
  onCompare,
}) {
  if (!open) return null;
  const entries = Object.entries(carts);

  return (
    <SheetWrapper
      onClose={onClose}
      title={`Cart drafts (${entries.length})`}
      height="55%"
    >
      <div style={{ padding: "0 14px 24px" }}>
        {entries.map(([rkey, c]) => {
          const r = MENUS[rkey];
          const t = calcCartTotals(c, r);
          const isActive = rkey === activeRestaurant;
          const isTier3 = r.tier === 3;
          const tier3MinTotal = isTier3
            ? r.estimatedCart.reduce(
                (s, l) => s + l.ppMin * profile.headcount,
                0,
              )
            : 0;
          const tier3MaxTotal = isTier3
            ? r.estimatedCart.reduce(
                (s, l) => s + l.ppMax * profile.headcount,
                0,
              )
            : 0;
          return (
            <button
              key={rkey}
              onClick={() => {
                onSwitch(rkey);
                onClose();
              }}
              style={{
                display: "flex",
                alignItems: "center",
                gap: 10,
                width: "100%",
                padding: "10px 12px",
                marginBottom: 6,
                borderRadius: 11,
                background: isActive ? T.brandLight : T.card,
                border: isTier3
                  ? `1px dashed ${isActive ? T.warning : T.border}`
                  : `1px solid ${isActive ? T.brand : T.border}`,
                cursor: "pointer",
                fontFamily: font,
                textAlign: "left",
              }}
            >
              <div
                style={{
                  width: 40,
                  height: 40,
                  borderRadius: 9,
                  flexShrink: 0,
                  background: `linear-gradient(135deg, ${r.brandColor}, ${r.brandColorAccent})`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: 18,
                  opacity: isTier3 ? 0.85 : 1,
                }}
              >
                {r.icon}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
                  <span
                    style={{ fontSize: 13, fontWeight: 600, color: T.text }}
                  >
                    {r.name}
                  </span>
                  {isTier3 && (
                    <span
                      style={{
                        fontSize: 8,
                        padding: "1px 5px",
                        borderRadius: 3,
                        background: T.warning,
                        color: "#fff",
                        fontWeight: 700,
                        letterSpacing: "0.04em",
                      }}
                    >
                      📍 T3
                    </span>
                  )}
                  {isActive && !isTier3 && (
                    <span
                      style={{
                        fontSize: 9,
                        padding: "1px 5px",
                        borderRadius: 3,
                        background: T.brand,
                        color: "#fff",
                        fontWeight: 700,
                        letterSpacing: "0.04em",
                      }}
                    >
                      EDITING
                    </span>
                  )}
                </div>
                <div
                  style={{ fontSize: 10, color: T.textTertiary, marginTop: 1 }}
                >
                  {isTier3
                    ? `Est. $${tier3MinTotal.toFixed(0)}–$${tier3MaxTotal.toFixed(0)} · quote-only`
                    : `${c.reduce((s, l) => s + l.qty, 0)} items · $${t.subtotal.toFixed(2)} · ${t.totalBites.toLocaleString()} Bites`}
                </div>
              </div>
            </button>
          );
        })}
        {entries.length >= 2 && (
          <button
            onClick={() => {
              onCompare();
              onClose();
            }}
            style={{
              width: "100%",
              padding: "11px 14px",
              marginTop: 6,
              borderRadius: 11,
              border: "none",
              background: `linear-gradient(135deg, ${T.brand}, ${T.brandDark})`,
              color: "#fff",
              fontSize: 12,
              fontWeight: 700,
              cursor: "pointer",
              fontFamily: font,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 6,
              boxShadow: `0 2px 8px ${T.brandGlow}`,
            }}
          >
            <span>↔</span>
            <span>
              Compare {entries.filter(([k]) => MENUS[k].tier !== 3).length}{" "}
              carts
            </span>
          </button>
        )}
      </div>
    </SheetWrapper>
  );
}

// ─── Tier 3 light cart inline ───
function TierThreeLightCart({ restaurant, profile }) {
  const minTotal = restaurant.estimatedCart.reduce(
    (s, l) => s + l.ppMin * profile.headcount,
    0,
  );
  const maxTotal = restaurant.estimatedCart.reduce(
    (s, l) => s + l.ppMax * profile.headcount,
    0,
  );
  const midTotal = (minTotal + maxTotal) / 2;
  const estBites = Math.round(midTotal * restaurant.estimatedBaseRate * 2);

  return (
    <div style={{ padding: "10px 14px" }}>
      {/* Discovery status card */}
      <div
        style={{
          background: T.card,
          borderRadius: 12,
          border: `1px dashed ${T.border}`,
          padding: "10px 12px",
          marginBottom: 10,
        }}
      >
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: 12,
            marginBottom: 8,
          }}
        >
          <div>
            <div
              style={{
                fontSize: 9,
                fontWeight: 700,
                color: T.textTertiary,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                marginBottom: 2,
              }}
            >
              You'd earn
            </div>
            <div
              style={{
                fontSize: 16,
                fontWeight: 600,
                color: T.textTertiary,
                fontFamily: fontDisplay,
              }}
            >
              ~{estBites.toLocaleString()}
            </div>
            <div
              style={{
                fontSize: 9,
                color: T.textTertiary,
                fontStyle: "italic",
                marginTop: 1,
              }}
            >
              if activated
            </div>
          </div>
          <div>
            <div
              style={{
                fontSize: 9,
                fontWeight: 700,
                color: T.textTertiary,
                letterSpacing: "0.06em",
                textTransform: "uppercase",
                marginBottom: 2,
              }}
            >
              Est. price
            </div>
            <div
              style={{
                fontSize: 14,
                fontWeight: 700,
                color: T.text,
                fontFamily: fontMono,
              }}
            >
              ${minTotal.toFixed(0)}–${maxTotal.toFixed(0)}
            </div>
            <div style={{ fontSize: 9, color: T.textTertiary, marginTop: 1 }}>
              ${(minTotal / profile.headcount).toFixed(0)}–$
              {(maxTotal / profile.headcount).toFixed(0)}/pp
            </div>
          </div>
        </div>
        <div
          style={{
            display: "inline-flex",
            alignItems: "center",
            gap: 5,
            padding: "3px 8px",
            borderRadius: 5,
            background: T.warningBg,
            color: T.warning,
            fontSize: 10,
            fontWeight: 600,
          }}
        >
          📍 Not yet partnered · quote-only
        </div>
      </div>

      {/* Estimated lines */}
      {restaurant.estimatedCart.map((line) => (
        <div
          key={line.id}
          style={{
            background: T.card,
            borderRadius: 11,
            border: `1px dashed ${T.border}`,
            padding: 11,
            marginBottom: 8,
          }}
        >
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "flex-start",
              gap: 10,
              marginBottom: 4,
            }}
          >
            <span
              style={{
                fontSize: 13,
                fontWeight: 600,
                color: T.text,
                fontFamily: fontDisplay,
                flex: 1,
              }}
            >
              {line.desc}
            </span>
            <span
              style={{
                fontSize: 12,
                fontWeight: 700,
                color: T.text,
                fontFamily: fontMono,
                whiteSpace: "nowrap",
              }}
            >
              ${(line.ppMin * profile.headcount).toFixed(0)}–$
              {(line.ppMax * profile.headcount).toFixed(0)}
            </span>
          </div>
          <div
            style={{
              fontSize: 10,
              color: T.textSecondary,
              lineHeight: 1.4,
              marginBottom: 5,
            }}
          >
            {line.detail}
          </div>
          <div style={{ fontSize: 10, color: T.textTertiary }}>
            <span style={{ fontSize: 11 }}>👥</span> {line.coverage}
          </div>
        </div>
      ))}

      {/* Helper note */}
      <div
        style={{
          padding: "9px 11px",
          borderRadius: 9,
          background: T.warningBg,
          border: `1px solid ${T.warning}33`,
          marginTop: 4,
          marginBottom: 10,
          fontSize: 10,
          color: T.textSecondary,
          lineHeight: 1.45,
        }}
      >
        <strong style={{ color: T.warning }}>💡 Estimate only.</strong> Final
        menu and pricing come from the restaurant when they respond to your
        quote or call.
      </div>
    </div>
  );
}

