// ─── AI inline message ───
function AIInlineMsg({ text, onDismiss }) {
  if (!text) return null;
  return (
    <div
      style={{
        padding: "10px 12px",
        margin: "10px 14px",
        borderRadius: 11,
        background: T.aiMsg,
        border: `1px solid ${T.border}`,
        display: "flex",
        gap: 8,
        alignItems: "flex-start",
        animation: "fadeIn 0.3s ease",
      }}
    >
      <div
        style={{
          width: 22,
          height: 22,
          borderRadius: 6,
          flexShrink: 0,
          background: `linear-gradient(135deg, ${T.brand}, ${T.brandDark})`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <span
          style={{
            color: "#fff",
            fontSize: 10,
            fontWeight: 700,
            fontFamily: fontDisplay,
          }}
        >
          W
        </span>
      </div>
      <div style={{ flex: 1, fontSize: 11.5, color: T.text, lineHeight: 1.5 }}>
        {text
          .split("**")
          .map((p, i) =>
            i % 2 === 1 ? (
              <strong key={i}>{p}</strong>
            ) : (
              <span key={i}>{p}</span>
            ),
          )}
      </div>
      <button
        onClick={onDismiss}
        style={{
          background: "transparent",
          border: "none",
          color: T.textTertiary,
          cursor: "pointer",
          fontSize: 13,
          padding: 0,
        }}
      >
        ✕
      </button>
    </div>
  );
}

